import{_ as t,a as r,o as a,a6 as o}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Place Order","description":"","frontmatter":{"outline":false,"examples":[{"id":"place-order-onsite","title":"Place Order (on-site payment)","description":"Cash-on-delivery or money-transfer — the order is created immediately.","query":"mutation createCheckoutOrder {\\n  createCheckoutOrder(input:{}) {\\n    checkoutOrder {\\n      id\\n      orderId\\n      redirect\\n      redirectUrl\\n      success\\n      message\\n    }\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createCheckoutOrder\\": {\\n      \\"checkoutOrder\\": {\\n        \\"id\\": \\"4814\\",\\n        \\"orderId\\": \\"554\\",\\n        \\"redirect\\": false,\\n        \\"redirectUrl\\": null,\\n        \\"success\\": true,\\n        \\"message\\": \\"Order placed successfully\\"\\n      }\\n    }\\n  }\\n}\\n"},{"id":"place-order-redirect","title":"Place Order (payment gateway)","description":"Stripe / PayU / PhonePe / Razorpay / PayPal — no order yet; redirect the shopper to complete payment.","query":"mutation createCheckoutOrder {\\n  createCheckoutOrder(input:{}) {\\n    checkoutOrder {\\n      id\\n      orderId\\n      redirect\\n      redirectUrl\\n      success\\n      message\\n    }\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createCheckoutOrder\\": {\\n      \\"checkoutOrder\\": {\\n        \\"id\\": \\"9372\\",\\n        \\"orderId\\": null,\\n        \\"redirect\\": true,\\n        \\"redirectUrl\\": \\"https://your-domain.com/stripe/redirect\\",\\n        \\"success\\": true,\\n        \\"message\\": \\"This payment method requires the shopper to complete payment on the gateway. Send them to redirectUrl; the order is created once the gateway confirms the payment.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/shop/mutations/place-order.md","filePath":"api/graphql-api/shop/mutations/place-order.md","lastUpdated":1787290888000}'),d={name:"api/graphql-api/shop/mutations/place-order.md"};function n(s,e,i,c,h,l){return a(),r("div",null,e[0]||(e[0]=[o('<h1 id="place-order" tabindex="-1">Place Order <a class="header-anchor" href="#place-order" aria-label="Permalink to &quot;Place Order&quot;">​</a></h1><p>Create an order from a cart and complete the checkout process.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This query supports both authenticated customers and guest users:</p><ul><li><strong>Authenticated customers</strong>: Provide a valid customer authentication token in the <code>Authorization</code> header. Obtain this token via the <a href="/api/graphql-api/shop/mutations/customer-login.html">Customer Login API</a>.</li><li><strong>Guest users</strong>: Provide the Guest Cart Token <code>cartToken</code> obtained from the <a href="/api/graphql-api/shop/mutations/create-cart.html">Create Cart mutation</a>.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Bearer &lt;accessToken&gt;</span></span></code></pre></div><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>ID</td><td>The cart id the order was placed from (numeric — this is an action result, not a fetchable IRI; use <code>orderId</code> for the created order).</td></tr><tr><td><code>orderId</code></td><td>String</td><td>The created order id — <strong>only set on the on-site path</strong>. <code>null</code> when a payment redirect is required (the order is created after the gateway confirms).</td></tr><tr><td><code>redirect</code></td><td>Boolean</td><td><code>true</code> when the payment method needs the shopper sent to a payment page before the order exists.</td></tr><tr><td><code>redirectUrl</code></td><td>String</td><td>The payment page to open when <code>redirect</code> is <code>true</code>; <code>null</code> otherwise.</td></tr><tr><td><code>success</code></td><td>Boolean</td><td><code>true</code> when the call succeeded — either the order was placed <strong>or</strong> a redirect is required. Order-placement <strong>failures</strong> are returned in <code>errors[]</code>, not here.</td></tr><tr><td><code>message</code></td><td>String</td><td>Human-readable result — &quot;order placed&quot;, or an explanation that the shopper must be redirected to complete payment.</td></tr></tbody></table><h3 id="two-outcomes" tabindex="-1">Two outcomes <a class="header-anchor" href="#two-outcomes" aria-label="Permalink to &quot;Two outcomes&quot;">​</a></h3><p>This mutation has two success shapes — branch on <code>redirect</code>:</p><ul><li><strong><code>redirect: false</code></strong> (cash-on-delivery, money-transfer) — the order exists; read <code>orderId</code>.</li><li><strong><code>redirect: true</code></strong> (stripe, payu, phonepe, razorpay, paypal) — <strong>no order yet</strong>. <code>orderId</code> is <code>null</code>; send the shopper to <code>redirectUrl</code> to pay. The order is created when the gateway returns to your success URL. <code>message</code> explains this so a client that only checks the payload knows why there is no order id.</li></ul><p>On a genuine failure (empty cart, missing address/shipping/payment, suspended account, minimum-order not met) the mutation returns <code>errors[]</code> with the exact reason and <code>checkoutOrder</code> is <code>null</code>.</p><h2 id="before-the-order-can-be-placed" tabindex="-1">Before the order can be placed <a class="header-anchor" href="#before-the-order-can-be-placed" aria-label="Permalink to &quot;Before the order can be placed&quot;">​</a></h2><p>Every step of the checkout must be complete. The mutation fails with <code>errors[]</code> and a <code>null</code> payload when any of them is outstanding:</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Satisfied by</th></tr></thead><tbody><tr><td>The cart holds at least one item</td><td><a href="/api/graphql-api/shop/mutations/add-to-cart.html">Add to Cart</a></td></tr><tr><td>A billing address is set</td><td><a href="/api/graphql-api/shop/mutations/set-billing-address.html">Set Checkout Address</a></td></tr><tr><td>A shipping address is set, for a cart with shippable items</td><td><a href="/api/graphql-api/shop/mutations/set-billing-address.html">Set Checkout Address</a></td></tr><tr><td>A shipping method is selected</td><td><a href="/api/graphql-api/shop/mutations/set-shipping-method.html">Set Shipping Method</a></td></tr><tr><td>A payment method is selected</td><td><a href="/api/graphql-api/shop/mutations/set-payment-method.html">Set Payment Method</a></td></tr></tbody></table><p>Stock is re-checked at this point as well, so an item that sold out while the shopper was in checkout fails the call even though every step was completed.</p><p>A coupon is not a prerequisite. An invalid or expired one blocks the order, but placing an order without any coupon is the normal case.</p><h2 id="order-status-after-placing" tabindex="-1">Order status after placing <a class="header-anchor" href="#order-status-after-placing" aria-label="Permalink to &quot;Order status after placing&quot;">​</a></h2><p>A newly placed order is <code>pending</code>, or <code>pending_payment</code> while a redirect gateway completes. It then moves through the store&#39;s own workflow:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>pending</code></td><td>Order created and awaiting processing.</td></tr><tr><td><code>pending_payment</code></td><td>Awaiting payment confirmation from the gateway.</td></tr><tr><td><code>processing</code></td><td>Payment confirmed and the order is being prepared.</td></tr><tr><td><code>completed</code></td><td>Fully invoiced and shipped.</td></tr><tr><td><code>canceled</code></td><td>Canceled before fulfilment.</td></tr><tr><td><code>closed</code></td><td>Closed after a refund.</td></tr><tr><td><code>fraud</code></td><td>Flagged by the store as fraudulent.</td></tr></tbody></table><h2 id="what-happens-on-success" tabindex="-1">What happens on success <a class="header-anchor" href="#what-happens-on-success" aria-label="Permalink to &quot;What happens on success&quot;">​</a></h2><ul><li>The cart is emptied and its token stops resolving.</li><li>The order confirmation email is sent to the shopper.</li><li>Stock is decremented for every ordered item.</li><li>The shopper can track the order through <a href="/api/graphql-api/shop/queries/get-customer-orders.html">Get Customer Orders</a>.</li></ul><p>On a redirect payment none of this happens yet — the cart survives until the gateway returns and the order is actually created.</p><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/mutations/create-cart.html">Create Cart</a></li><li><a href="/api/graphql-api/shop/mutations/set-billing-address.html">Set Checkout Address</a></li><li><a href="/api/graphql-api/shop/mutations/set-payment-method.html">Set Payment Method</a></li><li><a href="/api/graphql-api/shop/queries/get-customer-orders.html">Get Customer Orders</a></li></ul>',25)]))}const m=t(d,[["render",n]]);export{u as __pageData,m as default};
